package com.narratiaa.goals;

import com.narratiaa.auth.AuthService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.sql.*;import java.time.*;import java.util.*;

@RestController @RequestMapping("/api")
public class ReaderController {
  private final AuthService auth;private final JdbcTemplate db;public ReaderController(AuthService a,JdbcTemplate d){auth=a;db=d;}private long uid(HttpServletRequest r){return auth.requireUser(r).id();}
  private Map<String,Object> goal(long u){db.update("INSERT INTO goals(user_id) VALUES(?) ON CONFLICT(user_id) DO NOTHING",u);return db.queryForObject("SELECT daily_type,daily_target,annual_books FROM goals WHERE user_id=?",(x,n)->Map.of("dailyType",x.getString(1),"dailyTarget",x.getInt(2),"annualBooks",x.getInt(3)),u);}
  @GetMapping("/goals")Map<String,Object> goals(HttpServletRequest r){return Map.of("goal",goal(uid(r)));}
  @PutMapping("/goals")Map<String,Object> goals(HttpServletRequest r,@RequestBody Map<String,Object>b){long u=uid(r);goal(u);db.update("UPDATE goals SET daily_type=?,daily_target=?,annual_books=?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?","minutes".equals(b.get("dailyType"))?"minutes":"pages",positive(b.get("dailyTarget"),30),positive(b.get("annualBooks"),12),u);return Map.of("goal",goal(u));}
  @GetMapping("/onboarding")Map<String,Object> onboarding(HttpServletRequest r){long u=uid(r);db.update("INSERT INTO reader_profiles(user_id) VALUES(?) ON CONFLICT(user_id) DO NOTHING",u);var p=db.queryForObject("SELECT favorite_genres,onboarding_completed FROM reader_profiles WHERE user_id=?",(x,n)->Map.of("favoriteGenres",x.getString(1),"onboardingCompleted",x.getInt(2)),u);return Map.of("profile",p,"goal",goal(u));}
  @PutMapping("/onboarding")Map<String,String> onboarding(HttpServletRequest r,@RequestBody Map<String,Object>b){long u=uid(r);db.update("INSERT INTO reader_profiles(user_id) VALUES(?) ON CONFLICT(user_id) DO NOTHING",u);Object g=b.get("favoriteGenres");String genres=g instanceof Collection<?> c?String.join(",",c.stream().map(String::valueOf).toList()):"";db.update("UPDATE reader_profiles SET favorite_genres=?,onboarding_completed=1,updated_at=CURRENT_TIMESTAMP WHERE user_id=?",genres,u);goal(u);db.update("UPDATE goals SET daily_type=?,daily_target=?,annual_books=?,updated_at=CURRENT_TIMESTAMP WHERE user_id=?","minutes".equals(b.get("dailyType"))?"minutes":"pages",positive(b.get("dailyTarget"),30),positive(b.get("annualBooks"),12),u);return Map.of("message","Onboarding completed.");}
  @GetMapping("/stats")Map<String,Object> stats(HttpServletRequest r){long u=uid(r);var totals=db.queryForObject("SELECT COUNT(*),COALESCE(SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END),0),COALESCE(SUM(current_page),0) FROM books WHERE user_id=?",(x,n)->new long[]{x.getLong(1),x.getLong(2),x.getLong(3)},u);var reads=db.queryForObject("SELECT COALESCE(SUM(end_page-start_page),0),COALESCE(SUM(minutes),0) FROM reading_sessions WHERE user_id=?",(x,n)->new long[]{x.getLong(1),x.getLong(2)},u);var today=db.queryForObject("SELECT COALESCE(SUM(end_page-start_page),0),COALESCE(SUM(minutes),0) FROM reading_sessions WHERE user_id=? AND read_at::date=CURRENT_DATE",(x,n)->Map.of("pages",x.getLong(1),"minutes",x.getLong(2)),u);var activity=db.query("SELECT read_at::date,SUM(end_page-start_page),SUM(minutes) FROM reading_sessions WHERE user_id=? AND read_at::date>=CURRENT_DATE-29 GROUP BY read_at::date ORDER BY read_at::date",(x,n)->Map.of("date",x.getObject(1),"pages",x.getLong(2),"minutes",x.getLong(3)),u);Set<String> dates=new HashSet<>();activity.forEach(a->dates.add(String.valueOf(a.get("date"))));int streak=0;for(LocalDate d=LocalDate.now();dates.contains(d.toString());d=d.minusDays(1))streak++;Integer year=db.queryForObject("SELECT COUNT(*) FROM books WHERE user_id=? AND status='completed' AND EXTRACT(YEAR FROM finished_at)=EXTRACT(YEAR FROM CURRENT_DATE)",Integer.class,u);var s=new LinkedHashMap<String,Object>();s.put("totalBooks",totals[0]);s.put("completedBooks",totals[1]);s.put("libraryPages",totals[2]);s.put("pagesRead",reads[0]);s.put("minutesRead",reads[1]);s.put("today",today);s.put("activity",activity);s.put("streak",streak);s.put("completedThisYear",year);s.put("goal",goal(u));return Map.of("stats",s);}
  private int positive(Object o,int d){try{return Math.max(1,Integer.parseInt(String.valueOf(o)));}catch(Exception e){return d;}}
}
